function w({registerIndicator:h,sourceValues:k,nulls:y}){const f=o=>{let r=1,t=1;const s=o/2;for(let n=1;n<=25;n++)t*=s/n,r+=t*t;return r},d=(o,r)=>{const t=f(r),s=o-1,n=new Array(o);let l=0;for(let e=0;e<o;e++){const u=s>0?2*e/s-1:0,i=1-u*u,c=i>0?Math.sqrt(i):0,a=t>0?f(r*c)/t:1;n[e]=a,l+=a}if(l>0)for(let e=0;e<o;e++)n[e]/=l;return n};h({id:"oa-kaiser",name:"Kaiser Window Moving Average (KAISER)",category:"Trends FIR",placement:"onchart",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"period",type:"number",label:"Period",default:14,min:2,max:5e3,step:1},{key:"beta",type:"number",label:"Beta (shape)",default:3,min:0,max:20,step:.1,tooltip:"0=rectangular(SMA), 3=good general, 5.65 approximates Blackman, 8.6=Hamming-like"}],plots:[{key:"kaiser",type:"line",title:"KAISER",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,r){const t=Math.max(2,Math.floor(Number(r.period)||14)),s=r.beta,n=s===""||s==null?3:Number(s),l=Number.isFinite(n)?Math.min(20,Math.max(0,n)):3,e=k(o,r.source??"close"),u=d(t,l),i=o.length,c=new Array(i).fill(NaN);for(let a=0;a<i;a++){const g=Number.isFinite(e[a])?e[a]:0;if(a<t-1){c[a]=g;continue}let p=0;for(let m=0;m<t;m++){const b=e[a-t+1+m];p+=(Number.isFinite(b)?b:0)*u[m]}c[a]=p}return{kaiser:y(c)}}})}export{w as default};
